   ratified vault. ***
   anchor      : HUB_DISTRIBUTION_CHANNEL   (kind: hub, origin: map.anchor)
   track       : unratified
   history     : SCD2
   feeders     : 1 emitted of 1 (one per source view AND run)
   runs        : 1 -- opus_health_v2
   payload     : 1 attribute(s), NULL-PADDED TO THE SATELLITE
   grain       : ONE ROW PER HUB_DISTRIBUTION_CHANNEL_HK
   hashdiff    : SAT_CHANNEL_DIGITAL_INTEGRATION_HASHDIFF (builder decision BD1), GUARDED against an all-null input (s5.5):
                 without the guard every all-null row hashes to ONE value and the
                 satellite collapses to one row, which looks like change detection.
*/

with feeders as (
    select
        md5(upper('HUB_DISTRIBUTION_CHANNEL|' || (HUB_DISTRIBUTION_CHANNEL_BK__USER_TRANS_KEY_NO))) as HUB_DISTRIBUTION_CHANNEL_HK
        , USER_ID as SUBMITTING_USER_LOGIN_IDENTIFIER
        , 'BJAZ_PMSBY_DATA_WEB_SERVICE' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_pmsby_data_web_service') }}
    where (nullif(trim(USER_TRANS_KEY_NO),'')) is not null
),

resolved as (
    select
        HUB_DISTRIBUTION_CHANNEL_HK,
        max(case when SOURCE_RUN = 'opus_health_v2' then SUBMITTING_USER_LOGIN_IDENTIFIER end) as SUBMITTING_USER_LOGIN_IDENTIFIER,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_DISTRIBUTION_CHANNEL_HK
),

hashed as (
    select
        *,
        case when SUBMITTING_USER_LOGIN_IDENTIFIER is not null
                     then md5(upper(coalesce(cast(SUBMITTING_USER_LOGIN_IDENTIFIER as varchar), '')))
                end as SAT_CHANNEL_DIGITAL_INTEGRATION_HASHDIFF
    from resolved
)

select * from hashed
where HUB_DISTRIBUTION_CHANNEL_HK is not null
  and SAT_CHANNEL_DIGITAL_INTEGRATION_HASHDIFF is not null
